 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    out = [row[:] for row in grid]
    marker = lambda v: v not in (0, 2)

    # Continue the rectangle's rows away from any marker lying on that row.
    for r in range(r0, r1 + 1):
        left_blocked = any(marker(grid[r][c]) for c in range(c0))
        right_blocked = any(marker(grid[r][c]) for c in range(c1 + 1, w))
        if not left_blocked:
            for c in range(c0 - 1, -1, -1):
                if grid[r][c] == 0:
                    out[r][c] = 2
        if not right_blocked:
            for c in range(c1 + 1, w):
                if grid[r][c] == 0:
                    out[r][c] = 2

    # Continue the rectangle's columns away from any marker lying on that column.
    for c in range(c0, c1 + 1):
        up_blocked = any(marker(grid[r][c]) for r in range(r0))
        down_blocked = any(marker(grid[r][c]) for r in range(r1 + 1, h))
        if not up_blocked:
            for r in range(r0 - 1, -1, -1):
                if grid[r][c] == 0:
                    out[r][c] = 2
        if not down_blocked:
            for r in range(r1 + 1, h):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out
